// QA joint display-naming acceptance (display-naming box 6.1, Tier 1). The
// FULL production path in one test: a REAL cmd/mellifera server subprocess
// (the qaSerialStartServer harness) running REAL serial-scanner and
// serial-parser plugin subprocesses over a REAL fixture library, then the
// store→api→module naming joints asserted over the REAL HTTP surface:
//
//   - module default: with NO library naming option set, the serial seed's
//     display.item_name template (served verbatim in the GET /libraries/{id}
//     module block) composes the episode display_name on the item list AND
//     detail, and the series display_name follows the clean chain
//     (override > parser title > dir_name_raw > last segment),
//   - option re-compose: PATCH naming_element_name re-composes every served
//     display_name on the NEXT read — the single scan happens once at the
//     top and no rebuild/rescan runs anywhere below, so a passing assertion
//     here is the no-invalidation contract itself,
//   - precedence: the series title override beats the option-composed name
//     (the override flows INTO the composition as the {title} token), the
//     item's own override beats the composed name entirely, and clearing
//     both restores the option-composed tier; a Cyrillic override passes
//     through byte-verbatim (display.go's no-normalization contract),
//   - group style: naming_group_style "raw" switches the series chain to
//     override > dir_name_raw (the parser title is skipped) and the
//     composed episode {title} follows it; "" resets to clean,
//   - element reset: naming_element_name "" restores the module default.
//
// HERMETIC: the library root and the server's MELLIFERA_DATA_DIR both anchor
// under t.TempDir() (the open datadir-CWD-hermeticity backlog item), and the
// shikimori stage's upstream fetch is pinned to a local stub — this fixture's
// derived title has no candidate there, so the stage soft-fails and every row
// still settles ready (the film joint's proven posture); no test byte reaches
// the network. The expected names are re-derived by hand from the shipped
// grammar semantics (season-marker cut → "QA Naming Vault"; %02d padding) and
// from the seed's byte-exact U+00B7 separator — a hard-coded value in the
// shipped code cannot pass by coincidence.
//
// Every helper is qaDisplay-prefixed to stay collision-free in package itest;
// the shared qa serial harness (buildBinary/qaSerialStartServer/scanLibrary/
// qaSerialWaitSettled/…) is reused as-is.
package itest

import (
	"fmt"
	"net/http"
	"os/exec"
	"path/filepath"
	"testing"
)

// Fixture identity constants — independent of the plugin suites' fixtures AND
// of the other qa tests' names (no-coincidence discipline). The directory's
// trailing S01 marker is the season the parser cuts from the clean title and
// stamps on the series row; the episode filenames carry the canonical SxxExx
// token the parser reads as (season 1, episode n).
const (
	qaDisplayDir     = "QA Naming Vault S01"
	qaDisplayEp1Rel  = qaDisplayDir + "/QA Naming Vault S01E01.mkv"
	qaDisplayEp2Rel  = qaDisplayDir + "/QA Naming Vault S01E02.mkv"
	qaDisplayTitle   = "QA Naming Vault"     // the season-marker cut the parser writes
	qaDisplayRawName = "QA Naming Vault S01" // parsed.dir_name_raw, verbatim
)

// The seed's module-default template, byte-exact (registry.go: U+00B7 MIDDLE
// DOT between {title} and S — written as the escape so the byte contract
// survives any editor mangling). The expected composed names re-derive it by
// hand: %02d padding renders season/episode 1 as "01".
const (
	qaDisplayDefaultTmpl = "{title} · S{season}E{episode}"
	qaDisplayDefaultEp1  = "QA Naming Vault · S01E01"
	qaDisplayDefaultEp2  = "QA Naming Vault · S01E02"
)

// The option template the PATCH phase installs and its hand-derived output —
// free text proves the pass-through grammar, the season token proves the
// option path still zero-pads.
const (
	qaDisplayOptionTmpl = "{title} [S{season} E{episode}]"
	qaDisplayOptionEp1  = "QA Naming Vault [S01 E01]"
	qaDisplayOptionEp2  = "QA Naming Vault [S01 E02]"
)

// The override names. The series one is Cyrillic on purpose: the override
// flows INTO the composed episode name as the {title} token, so a byte-exact
// composed assertion proves the no-normalization passthrough at the joint.
const (
	qaDisplaySeriesOverride = "Переименованный QA Vault"
	qaDisplayItemOverride   = "QA Pilot (Особая)"
)

